def stream_rows(resource, transform):
    try:
        while True:
            row = resource.read_next()
            if row is None:
                break
            yield transform(row)
    except GeneratorExit:
        # explicit close(): cleanup errors propagate
        resource.close()
        raise
    except BaseException:
        # iteration/transform error: preserve the original over cleanup errors
        try:
            resource.close()
        except Exception:
            pass
        raise
    resource.close()
