from .service import stream_rows

def take(resource, transform, limit):
    if limit <= 0:
        return []
    stream = stream_rows(resource, transform)
    result = []
    try:
        for row in stream:
            result.append(row)
            if len(result) >= limit:
                break
    except BaseException:
        try:
            stream.close()
        except Exception:
            pass
        raise
    stream.close()
    return result
